});

const localizedStrings: CalendarStrings = {
  ...defaultDatePickerStrings,
  days: ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'],
  shortDays: ['D', 'L', 'M', 'M', 'J', 'V', 'S'],
  months: [
